export function tw(classNames: string | undefined | null): string {
  if (!classNames) return "";

  const utilities = new Set<string>();
  for (const className of classNames.split(/\s+/)) {
    for (const utility of utilityClasses[className]?.split(/\s+/) ?? []) {
      utilities.add(utility);
    }
  }

  return [classNames, ...utilities].join(" ").trim();
}
